L23_1.m_fTalkTime = 0.03
L23_1.m_Talk_JPN = "\226\128\166\226\128\166\227\129\157\227\129\134\227\129\167\227\129\153\227\128\130\230\165\189\229\156\146\227\129\174\233\129\139\229\145\189\227\129\175\231\167\129\227\129\168\228\184\128\227\129\164\227\129\171\227\129\170\227\129\163\227\129\166\227\129\132\227\129\166\227\128\129\229\167\139\227\129\190\227\130\138\227\129\168\231\181\130\227\130\143\227\130\138\227\130\146\229\133\177\230\156\137\227\129\151\227\129\166\227\129\132\227\130\139\227\129\174\227\129\167\227\129\153\227\128\130"
L23_1.m_Talk_ENG = "...That's right. The fate of the Promised Land is bound together with mine, so it begins and ends with me."
L23_1.m_Talk_TWN = "\226\128\166\226\128\166\230\178\146\233\140\175\227\128\130\230\168\130\229\156\146\231\154\132\229\145\189\233\129\139\229\146\140\230\136\145\231\182\129\229\156\168\228\184\128\232\181\183\239\188\140\233\150\139\229\167\139\232\136\135\231\181\144\230\157\159\233\131\189\230\156\131\229\144\140\230\153\130\231\153\188\231\148\159\227\128\130"
