L24_1.m_fTalkTime = 0.03
L24_1.m_Talk_JPN = "\230\165\189\229\156\146\227\129\175\231\167\129\227\129\171\231\148\159\227\129\141\227\129\166\227\129\132\227\129\166\227\129\187\227\129\151\227\129\132\227\129\159\227\130\129\227\128\129\230\175\142\230\151\165\230\173\187\227\130\146\231\185\176\227\130\138\232\191\148\227\129\153\227\129\147\227\129\168\227\129\167\231\181\130\230\156\171\227\129\139\227\130\137\233\128\131\227\130\140\227\130\139\227\129\147\227\129\168\227\129\140\227\129\167\227\129\141\227\129\190\227\129\153\227\128\130"
